 46	function startManualFailAbortMonitor(env: Env, reviewId: string): { signal: AbortSignal; stop: () => void } {
 47	  const controller = new AbortController();
 48	  let stopped = false;
 49	  let polling = false;
 50	  let timer: ReturnType<typeof setInterval> | null = null;
 51	
 52	  const stop = (): void => {
 53	    if (stopped) {
 54	      return;
 55	    }
 56	    stopped = true;
 57	    if (timer !== null) {
 58	      clearInterval(timer);
 59	      timer = null;
 60	    }
 61	  };
 62	
 63	  const poll = async (): Promise<void> => {
 64	    if (stopped || polling || controller.signal.aborted) {
 65	      return;
 66	    }
 67	    polling = true;
 68	    try {
 69	      const latest = await getReviewRun(env.DB, reviewId);
 70	      if (isManuallyFailedReview(latest)) {
 71	        controller.abort();
 72	        stop();
 73	      }
 74	    } catch {
 75	      // Best-effort polling only; transient read failures must not become unhandled rejections.
 76	    } finally {
 77	      polling = false;
 78	    }
 79	  };
 80	
 81	  timer = setInterval(() => {
 82	    void poll();
 83	  }, 250);
 84	  void poll();
 85	
 86	  return { signal: controller.signal, stop };
 87	}
