 99	    }
100	    return;
101	  }
102	
103	  let review: ReviewRunResponse | null = null;
104	  const manualFailAbortMonitor = startManualFailAbortMonitor(env, reviewId);
105	  try {
106	    review = await getReviewRun(env.DB, reviewId);
107	    if (!review) {
108	      return;
109	    }
110	
111	    const payload = await getReviewRunRequestPayload(env.DB, reviewId);
112	    if (!payload) {
113	      await updateReviewRunStatus(env.DB, reviewId, 'failed', {
114	        errorCode: 'review_not_found',
115	        errorMessage: 'Review request payload no longer exists',
116	      });
117	      await appendReviewEvent(env.DB, {
118	        reviewId,
119	        eventType: 'review_failed',
120	        payload: {
121	          code: 'review_not_found',
122	          message: 'Review request payload no longer exists',
123	        },
124	      });
125	      return;
126	    }
127	
128	    const reviewContext = await assembleReviewContextBootstrap(env, review, payload, options);
129	    const latestBeforeExecution = await loadLatestReviewUnlessManuallyFailed(env, reviewId);
130	    if (!latestBeforeExecution) {
131	      return;
132	    }
133	    const report = await executeReviewRun(env, review, payload, reviewContext, {
134	      ...options,
135	      abortSignal: manualFailAbortMonitor.signal,
136	    });
137	    const latest = await loadLatestReviewUnlessManuallyFailed(env, reviewId);
138	    if (!latest) {
139	      return;
140	    }
141	    await finalizeSuccessfulReview(env, reviewId, payload, report, {
142	      expectedAttemptCount: review.attemptCount,
143	      allowRetryScheduling: options?.allowRetryScheduling,
144	    });
145	    const latestAfterFinalize = await loadLatestReviewUnlessManuallyFailed(env, reviewId);
146	    if (!latestAfterFinalize || latestAfterFinalize.status !== 'succeeded') {
147	      return;
148	    }
149	    const continuation = await continueReviewSessionAfterSuccessfulPass(env, latestAfterFinalize, report);
150	    if (continuation.nextReviewId) {
151	      await runReviewInlineWithRetries(env, continuation.nextReviewId, 4, options);
152	    }
153	  } catch (error) {
154	    const message = formatReviewAnalysisError(error, {
155	      openrouterApiKey: readOptionalString(options?.openrouterApiKey),
156	    });
157	    const latest = await loadLatestReviewUnlessManuallyFailed(env, reviewId);
158	    if (!latest) {
159	      return;
160	    }
161	    const attemptCount = review?.attemptCount ?? latest?.attemptCount ?? 0;
162	
163	    const allowRetryScheduling = options?.allowRetryScheduling !== false;
164	    if (allowRetryScheduling && shouldRetryReviewError(error) && attemptCount <= 2) {
165	      const retryScheduled = await scheduleReviewRetryIfCurrent(env, reviewId, {
166	        attemptCount,
167	        message,
168	        reason: message.slice(0, 500),
169	      });
170	      if (retryScheduled) {
171	        throw new QueueRetryError('Review transient failure; retry requested');
172	      }
173	    }
174	
175	    const contextAssemblyErrorCode = error instanceof ReviewContextAssemblyError ? error.code : null;
176	    const finalErrorCode = contextAssemblyErrorCode ?? 'review_execution_failed';
177	    await finalizeFailedReviewIfCurrent(env, reviewId, {
178	      errorCode: finalErrorCode,
179	      message,
180	      contextAssemblyErrorCode,
181	      expectedAttemptCount: attemptCount,
182	    });
183	  } finally {
184	    manualFailAbortMonitor.stop();
185	  }
186	}
