191	export async function runReviewInlineWithRetries(
192	  env: Env,
193	  reviewId: string,
194	  maxCycles = 4,
195	  options?: ReviewRunExecutionOptions
196	): Promise<void> {
197	  for (let cycle = 0; cycle < maxCycles; cycle += 1) {
198	    try {
199	      await processReviewRun(env, reviewId, options);
