208	    if (latest.status !== 'queued') {
209	      return;
210	    }
211	    if (latest.error?.code !== 'retry_scheduled') {
212	      return;
213	    }
214	  }
215	
216	  await finalizeInlineRetryExhaustion(env, reviewId);
