 79	/**
 80	 * Schedules a retry only if the same running attempt is still current.
 81	 * Returns false when another transition (for example manual fail) won the race.
 82	 */
 83	export async function scheduleReviewRetryIfCurrent(
 84	  env: Env,
 85	  reviewId: string,
 86	  input: {
 87	    attemptCount: number;
 88	    message: string;
 89	    reason: string;
 90	    extraPayload?: Record<string, unknown>;
 91	    throwMessage?: string;
 92	  }
 93	): Promise<boolean> {
 94	  const now = new Date().toISOString();
 95	  const transitioned = await env.DB
 96	    .prepare(
 97	      `UPDATE review_runs SET status = ?,
 98	           updated_at = ?,
 99	           started_at = NULL,
100	           finished_at = NULL,
101	           report_json = NULL,
102	           markdown_summary = NULL,
103	           error_code = ?,
104	           error_message = ?
105	       WHERE id = ? AND status = 'running' AND attempt_count = ?`
106	    )
107	    .bind('queued', now, 'retry_scheduled', input.message, reviewId, input.attemptCount)
108	    .run();
109	
110	  if ((transitioned.meta?.changes ?? 0) === 0) {
111	    return false;
112	  }
113	
114	  await replaceReviewFindings(env.DB, reviewId, []);
115	  await appendReviewEvent(env.DB, {
116	    reviewId,
117	    eventType: 'review_retry_scheduled',
118	    payload: {
119	      attemptCount: input.attemptCount,
120	      maxRetries: REVIEW_MAX_RETRIES,
121	      reason: input.reason,
122	      ...(input.extraPayload ?? {}),
123	    },
124	  });
125	  return true;
126	}
