128	/**
129	 * Handles the case where a review could not be claimed because another worker may already be running it.
130	 * Detects stale-running reviews and either schedules a retry or marks them failed.
131	 */
132	export async function handleUnclaimedReviewRun(
133	  env: Env,
134	  reviewId: string,
135	  existing: ReviewRunResponse,
136	  allowRetryScheduling: boolean
137	): Promise<void> {
138	  if (existing.status !== 'running') {
139	    return;
140	  }
141	
142	  const attemptTimeoutMs = parseTimeoutMs(env.ATTEMPT_TIMEOUT_MS, DEFAULT_REVIEW_ATTEMPT_TIMEOUT_MS);
143	  const staleThresholdMs = attemptTimeoutMs + REVIEW_STALE_GRACE_MS;
144	  const startedAtMs = toTimestampMs(existing.startedAt) ?? toTimestampMs(existing.updatedAt) ?? toTimestampMs(existing.createdAt);
145	  const staleForMs = startedAtMs === null ? null : Date.now() - startedAtMs;
146	  const isStale = typeof staleForMs === 'number' && staleForMs >= staleThresholdMs;
147	  if (!isStale) {
148	    throw new QueueRetryError('Review run is already running; defer redelivery');
149	  }
150	
151	  const staleForSeconds = Math.floor((staleForMs ?? 0) / 1000);
152	  const message = `Review execution stalled in running state for ${staleForSeconds}s (timeout threshold ${Math.floor(staleThresholdMs / 1000)}s).`;
153	  const attemptCount = existing.attemptCount ?? 0;
154	  if (allowRetryScheduling && attemptCount <= REVIEW_MAX_RETRIES) {
155	    await scheduleReviewRetry(env, reviewId, {
156	      attemptCount,
157	      message,
158	      reason: 'stale_running_timeout',
159	      extraPayload: { staleForSeconds },
160	      throwMessage: 'Review stale-running recovery requested',
161	    });
162	  }
163	
164	  await replaceReviewFindings(env.DB, reviewId, []);
165	  await updateReviewRunStatus(env.DB, reviewId, 'failed', {
166	    report: null,
167	    markdownSummary: null,
168	    errorCode: 'review_execution_timeout',
169	    errorMessage: message,
170	  });
171	  await appendReviewEvent(env.DB, {
172	    reviewId,
173	    eventType: 'review_failed',
174	    payload: {
175	      code: 'review_execution_timeout',
176	      message,
177	    },
178	  });
179	}
