 39	export function createReviewEventsStream(
 40	  env: Env,
 41	  reviewId: string,
 42	  request: Request,
 43	  initialStatus: ReviewRunStatus,
 44	  fromSeq: number
 45	): ReadableStream<Uint8Array> {
 46	  return new ReadableStream<Uint8Array>({
 47	    async start(controller) {
 48	      const encoder = new TextEncoder();
 49	      try {
 50	        let cursor = fromSeq;
 51	        let currentStatus = initialStatus;
 52	        let lastHeartbeatAt = Date.now();
 53	        let sawTerminalEvent = false;
 54	        let terminalGraceDeadline: number | null = null;
 55	        let pollCount = 0;
 56	
 57	        const write = (chunk: string): void => {
 58	          controller.enqueue(encoder.encode(chunk));
 59	        };
 60	
 61	        const writePersistedEvents = async (): Promise<void> => {
 62	          const persistedEvents = await listReviewEvents(env.DB, reviewId, cursor);
 63	          for (const item of persistedEvents) {
 64	            cursor = item.seq;
 65	            if (isTerminalEventType(item.eventType)) {
 66	              sawTerminalEvent = true;
 67	              currentStatus = statusFromTerminalEventType(item.eventType) ?? currentStatus;
 68	            }
 69	            write(
 70	              formatSseDataWithId(item.seq, {
 71	                type: item.eventType,
 72	                reviewId,
 73	                seq: item.seq,
 74	                createdAt: item.createdAt,
 75	                ...(isRecord(item.payload) ? item.payload : { value: item.payload }),
 76	              })
 77	            );
 78	          }
 79	        };
 80	
 81	        await writePersistedEvents();
 82	        write(
 83	          formatSseData({
 84	            type: 'snapshot',
 85	            reviewId,
 86	            status: currentStatus,
 87	          })
 88	        );
 89	
 90	        while (isReviewStatusActive(currentStatus)) {
 91	          await sleep(REVIEW_STREAM_POLL_INTERVAL_MS);
 92	          pollCount += 1;
 93	          await writePersistedEvents();
 94	
 95	          if (pollCount % REVIEW_STREAM_STATUS_REFRESH_POLLS === 0) {
 96	            const latest = await getReviewRun(env.DB, reviewId);
 97	            if (!latest) {
 98	              write(
 99	                formatSseData({
100	                  type: 'error',
101	                  reviewId,
102	                  message: 'Review not found during event stream',
103	                })
104	              );
105	              break;
106	            }
107	            await recoverStaleRunningReviewIfNeeded(
108	              env,
109	              reviewId,
110	              latest,
111	              readReviewGithubTokenHeader(request),
112	              readOpenrouterApiKeyHeader(request),
113	              { markFailedWhenRetryUnavailable: false, noAuthTerminalGraceMs: REVIEW_STALE_NOAUTH_TERMINAL_GRACE_MS }
114	            );
115	            const refreshed = await getReviewRun(env.DB, reviewId);
116	            if (refreshed) {
117	              await failStaleRetryScheduledReviewIfNeeded(env, reviewId, refreshed);
118	            }
119	            const finalized = await getReviewRun(env.DB, reviewId);
120	            currentStatus = finalized?.status ?? refreshed?.status ?? latest.status;
121	          }
122	
123	          if (!isReviewStatusActive(currentStatus) && terminalGraceDeadline === null) {
124	            terminalGraceDeadline = Date.now() + REVIEW_TERMINAL_EVENT_GRACE_MS;
125	          }
126	          if (!isReviewStatusActive(currentStatus) && sawTerminalEvent) {
127	            break;
128	          }
129	          if (terminalGraceDeadline !== null && Date.now() >= terminalGraceDeadline) {
130	            break;
131	          }
132	          if (Date.now() - lastHeartbeatAt >= REVIEW_STREAM_HEARTBEAT_INTERVAL_MS) {
133	            write(
134	              formatSseData({
135	                type: 'heartbeat',
136	                reviewId,
137	                status: currentStatus,
138	              })
139	            );
140	            lastHeartbeatAt = Date.now();
141	          }
142	        }
143	
144	        const terminal = await getReviewRun(env.DB, reviewId);
145	        if (terminal) {
146	          await writePersistedEvents();
147	          write(
148	            formatSseData({
149	              type: 'terminal',
150	              reviewId,
151	              status: terminal.status,
152	            })
153	          );
154	        }
155	      } catch (error) {
156	        const message = error instanceof Error ? error.message : String(error);
157	        controller.enqueue(
158	          encoder.encode(
159	            formatSseData({
160	              type: 'error',
161	              reviewId,
162	              message,
163	            })
164	          )
165	        );
166	      }
167	      controller.close();
168	    },
169	  });
170	}

