function validateReviewOutputV2(payload: unknown): ReviewOutputV2 {
  const parsed = reviewOutputV2Schema.safeParse(payload);
  if (!parsed.success) {
    const errors = parsed.error.issues.map((issue) => {
      const path = issue.path.length === 0
