export async function handleGetReviewSession(
  sessionId: string,
  request: Request,
  env: Env,
  authContext?: AuthContext
): Promise<Response> {
  const effectiveAuthContext =
    authContext ??
    ({ accountId: 'self-hosted', isAdmin: false, isAuthenticated: false, isHostedMode: false } as const);

  const accessResponse = await requireReviewSessionAccess(env, sessionId, effectiveAuthContext);
  if (accessResponse) {
    return accessResponse;
  }

  let session = await getReviewSession(env.DB, sessionId);
  if (!session) {
    return jsonResponse({ error: 'Review session not found' }, 404);
  }
  if (session.latestReviewId) {
    const latestReview = await getReviewRun(env.DB, session.latestReviewId);
    if (latestReview) {
      await recoverStaleRunningReviewIfNeeded(
        env,
        latestReview.id,
        latestReview,
        readReviewGithubTokenHeader(request),
        readOpenrouterApiKeyHeader(request),
        { markFailedWhenRetryUnavailable: false, noAuthTerminalGraceMs: REVIEW_STALE_NOAUTH_TERMINAL_GRACE_MS }
      );
      const refreshedReview = await getReviewRun(env.DB, session.latestReviewId);
      if (refreshedReview) {
        await failStaleRetryScheduledReviewIfNeeded(env, refreshedReview.id, refreshedReview);
      }
      session = await getReviewSession(env.DB, sessionId);
      if (!session) {
        return jsonResponse({ error: 'Review session not found' }, 404);
      }
    }
  }

  return jsonResponse({ session });
}

export async function handleListReviewSessions(
  request: Request,
  env: Env,
  authContext?: AuthContext
): Promise<Response> {
  const effectiveAuthContext =
    authContext ??
    ({ accountId: 'self-hosted', isAdmin: false, isAuthenticated: false, isHostedMode: false } as const);

  const url = new URL(request.url);
  const rawLimit = url.searchParams.get('limit');
  const parsedLimit = rawLimit ? Number.parseInt(rawLimit, 10) : Number.NaN;
  const limit = Number.isFinite(parsedLimit) && parsedLimit > 0 ? Math.min(parsedLimit, 200) : 50;

  const rawRepo = url.searchParams.get('repo');
  const rawBranch = url.searchParams.get('branch');
  const repo = rawRepo === null ? undefined : normalizeRepoSlug(rawRepo);
  const branch = rawBranch === null ? undefined : normalizeBranchRef(rawBranch);

  if (rawRepo !== null && !repo) {
    return jsonResponse(
      {
        error: 'Invalid repo query parameter. Expected owner/repo.',
        code: 'invalid_review_session_query',
      },
      400
    );
  }

  if (rawBranch !== null && !branch) {
    return jsonResponse(
      {
        error: 'Invalid branch query parameter.',
        code: 'invalid_review_session_query',
      },
      400
    );
  }

  const accountId =
    effectiveAuthContext.isHostedMode && !effectiveAuthContext.isAdmin
      ? effectiveAuthContext.isAuthenticated && typeof effectiveAuthContext.accountId === 'string'
        ? effectiveAuthContext.accountId
        : '__no_account__'
      : undefined;

  if (accountId === '__no_account__') {
    return jsonResponse({ sessions: [] });
  }

  const sessions = await listReviewSessions(env.DB, {
    limit,
    accountId,
    repo,
    branch,
  });

  return jsonResponse({ sessions });
}

