  return new Promise((resolve) => setTimeout(resolve, ms));
}

export function resolveFromSequence(request: Request): number {
  const url = new URL(request.url);
  const fromParam = parseNonNegativeInteger(url.searchParams.get('from'));
  const lastEventId = parseNonNegativeInteger(request.headers.get('Last-Event-ID'));

  if (typeof lastEventId === 'number') {
    return lastEventId;
  }
  if (typeof fromParam === 'number') {
    return fromParam;
  }
  return 0;
}

