  return Boolean(value) && typeof value === 'object' && !Array.isArray(value);
}

export function isSeverityThreshold(value: unknown): value is 'low' | 'medium' | 'high' | 'critical' {
  return value === 'low' || value === 'medium' || value === 'high' || value === 'critical';
}

