      },
    } as unknown as DurableObjectState,
    storage,
    waitUntilPromises,
  };
}

function readStatus(storage: Map<string, StoredValue>): string | null {
  const state = storage.get('state');
  return typeof state?.status === 'string' ? state.status : null;
