    return {
      providerName: 'cloudflare_workers_ai',
      model: resolveCloudflareAiModel(model),
      aiBinding,
      gatewayConfig,
      endpoint,
      providerApiKey: providerApiKey || null,
      openrouterApiKey: openrouterApiKey || null,
    };
  }

  if (endpoint) {
    return {
      providerName: 'cloudflare_agents_sdk',
      model,
      aiBinding,
      gatewayConfig,
      endpoint,
      providerApiKey: providerApiKey || null,
      openrouterApiKey: openrouterApiKey || null,
    };
  }

  if (openrouterApiKey) {
    return {
      providerName: 'openrouter',
      model,
      aiBinding,
      gatewayConfig,
      endpoint,
      providerApiKey: providerApiKey || null,
      openrouterApiKey,
    };
  }

  return null;
}

