/**
 * Runs the model-backed review analysis loop against a hydrated deployment snapshot using
 * the read-only review tools and strict structured-output validation.
 */
export async function runWorkspaceDeploymentAgentAnalysis(
  env: Env,
  input: ReviewAgentPromptInput & {
    deploymentSandboxId: string;
    workspaceSandboxId?: string;
    modelOverride?: string;
    abortSignal?: AbortSignal;
  }
): Promise<ReviewAgentAnalysisResult | null> {
  const endpoint = (env.AGENT_SDK_URL ?? '').trim() || (env.AGENT_ENDPOINT ? 'https://nimbus-agent-endpoint.internal' : '');
  const requestProviderApiKey = readOptionalString((input as { providerApiKey?: string | null }).providerApiKey);
  const requestOpenrouterApiKey = readOptionalString(input.openrouterApiKey);

  const configuredModel =
    readOptionalString(input.modelOverride) ??
    readOptionalString(env.REVIEW_MODEL) ??
    readOptionalString(env.AGENT_MODEL) ??
    DEFAULT_REVIEW_MODEL;
  const providerSelection = selectReviewAgentProvider({
    env,
    model: configuredModel,
    endpoint,
    providerApiKey: requestProviderApiKey,
    openrouterApiKey: requestOpenrouterApiKey,
  });
  if (!providerSelection) {
    return null;
  }
  const model = providerSelection.model;
  const reasoningEffort =
    parseReviewReasoningEffort(readOptionalString(env.REVIEW_REASONING_EFFORT)) ?? DEFAULT_REVIEW_REASONING_EFFORT;
  const authToken = (env.AGENT_SDK_AUTH_TOKEN ?? '').trim() || null;
  const useAgentEndpointForGatewayReview =
    providerSelection.providerName === 'cloudflare_ai_gateway' && Boolean(endpoint) && Boolean(authToken);
  const effectiveProviderSelection = useAgentEndpointForGatewayReview
    ? {
        ...providerSelection,
        providerName: 'cloudflare_agents_sdk' as const,
        endpoint,
      }
    : providerSelection;
  const lifecycleEndpoint =
    effectiveProviderSelection.providerName === 'cloudflare_ai_gateway'
      ? `${effectiveProviderSelection.gatewayConfig?.baseUrl ?? ''}/chat/completions`
      : endpoint;
  let endpointHost: string | null = null;
  let endpointPath: string | null = null;
  try {
    const parsedEndpoint = new URL(lifecycleEndpoint);
    endpointHost = parsedEndpoint.host;
    endpointPath = parsedEndpoint.pathname;
  } catch {
    endpointHost = null;
    endpointPath = null;
  }

  const maxSteps = parseIntegerString(env.REVIEW_AGENT_MAX_STEPS, DEFAULT_REVIEW_AGENT_MAX_STEPS, 1, MAX_REVIEW_AGENT_MAX_STEPS);
  const maxFileBytes = parseIntegerString(env.REVIEW_AGENT_MAX_FILE_BYTES, DEFAULT_REVIEW_MAX_FILE_BYTES, 1_024, 200_000);
  let sandbox: SandboxClient | null = null;
  let shouldDestroy = false;
  try {
    if (input.workspaceSandboxId) {
      sandbox = await resolveReviewSandbox(env, input.workspaceSandboxId);
    } else {
      if (!env.WORKSPACE_ARTIFACTS && !env.SOURCE_BUNDLES) {
        throw new Error('WORKSPACE_ARTIFACTS or SOURCE_BUNDLES binding is required for review analysis');
      }
      const bundle =
        (env.WORKSPACE_ARTIFACTS ? await env.WORKSPACE_ARTIFACTS.get(input.sourceBundleKey) : null) ??
        (env.SOURCE_BUNDLES ? await env.SOURCE_BUNDLES.get(input.sourceBundleKey) : null);
      if (!bundle) {
        throw new Error(`Review source bundle not found: ${input.sourceBundleKey}`);
      }

      sandbox = await resolveReviewSandbox(env, input.deploymentSandboxId);
      await hydrateReviewSandbox(sandbox, await bundle.arrayBuffer());
      shouldDestroy = typeof sandbox.destroy === 'function';
    }
    if (!sandbox) {
      throw new Error('Review sandbox unavailable');
    }

    const { rootListing, diffSnapshot } = await snapshotInitialContext(sandbox, maxFileBytes);
    const prompt = buildReviewAgentPrompt(
      sanitizePromptInput({
        ...input,
        rootListing,
        diffSnapshot,
      })
    );
    if (input.onLifecycleEvent) {
      await input.onLifecycleEvent('review_analysis_prompt_built', {
        reviewContextId: input.reviewContext.id,
        reasoningEffort: reasoningEffort ?? null,
      });
    }

    const provider =
      effectiveProviderSelection.providerName === 'cloudflare_workers_ai'
        ? new CloudflareWorkersAiReviewProvider(effectiveProviderSelection.aiBinding!, validateReviewAgentAction)
        : effectiveProviderSelection.providerName === 'cloudflare_ai_gateway'
          ? new CloudflareAiGatewayReviewProvider(
              effectiveProviderSelection.gatewayConfig!,
              effectiveProviderSelection.providerApiKey,
              validateReviewAgentAction

